/** Sign in as {{env:E2E_ADMIN_USERNAME}} with password {{env:E2E_ADMIN_PASSWORD}} and verify the dashboard opens */
async function step01Signin(page: Page, { env, outputs }: StepContext): Promise<void> {
  // s_6e55ea — recorded on /login
  // @step 01-signin s_6e55ea/1
  await page.getByRole('textbox', { name: 'Username', exact: true }).fill(env.E2E_ADMIN_USERNAME);
  // @step 01-signin s_6e55ea/2
  await page.getByRole('textbox', { name: 'Password', exact: true }).fill(env.E2E_ADMIN_PASSWORD);
  // @step 01-signin s_6e55ea/3
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await expect(page).toHaveURL(/:\/\/[^/]+\/$/);
  await expect(page.getByText('You have successfully logged in.')).toBeVisible();
  // s_a80fb4 — recorded on /
  // @step 01-signin s_a80fb4/1
  outputs['01-signin.dashboard_heading'] = (await page.getByRole('heading', { name: 'Dashboard', exact: true }).innerText()).trim();
  // @step 01-signin s_a80fb4/2
  outputs['01-signin.final_url'] = page.url();
}

